{
  "name": "Senior Citizens Property Tax Freeze",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "statewide_program_name": "Low-Income Senior Citizens Assessment Freeze Homestead Exemption",
      "general_state_limit": "$75,000 total household income",
      "county_variation_note": "Some Illinois counties use a lower local limit for administering information or outreach materials, but the statewide exemption referenced by county assessor materials is commonly $75,000.",
      "household_definition": "Household income includes income of all persons using the property as their principal dwelling on January 1 of the assessment year.",
      "table": [
        {
          "household_size": "Not used for eligibility",
          "income_limit": "$75,000 total household income"
        }
      ]
    },
    "asset_limits": null,
    "other_requirements": [
      "Applicant must be 65 or older by December 31 of the assessment year.",
      "Applicant must own and occupy the property as a principal residence.",
      "Applicant must have owned and occupied the home for the required period used by the county assessor, commonly the prior year and current year or two consecutive years depending on county instructions.",
      "Applicant must typically file a renewal each year to keep the exemption.",
      "Applicant must already be receiving the senior homestead exemption in some counties before the freeze can be granted."
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "Freezes the property’s equalized assessed value (EAV) at the base year value when the senior first qualifies. The EAV does not increase while eligibility continues, but the actual tax bill can still change if tax rates change.",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online application through the local county assessor site, where available",
      "Mail or in-person filing with the county supervisor of assessments or assessor office",
      "Some counties provide a paper PTAX-340 form for return by mail"
    ],
    "processing_time": "No single statewide processing time was located; timing is handled by county assessors and is driven by local filing deadlines, often around July 1 for the application year.",
    "waitlist": null,
    "forms": [
      "PTAX-340 Low-Income Senior Citizens Assessment Freeze Homestead Exemption"
    ],
    "documents": [
      "Completed PTAX-340 form",
      "Proof of age if requested",
      "Federal income tax return and all schedules, if required by the county form instructions",
      "Any local supporting documents requested by the assessor",
      "Property index number or property address"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available in Illinois, administered locally by county assessor/supervisor of assessments offices.",
    "regional_variations": "Yes. Counties may differ on filing portal, mailing address, office contact, documentation requirements, and exact local instructions. Some county materials cite different administrative details, but the underlying statewide exemption is the same.",
    "offices_or_providers": [
      "Cook County Assessor’s Office, 118 North Clark Street, Room 320, Chicago, IL 60602, 312.443.7550",
      "Kane County Assessment Office, 719 Batavia Avenue, Geneva, IL 60134-3000",
      "Winnebago County Supervisor of Assessments, 404 Elm St. Rm. 301, Rockford, IL 61101, 815.319.4460",
      "County assessor or supervisor of assessments office in the applicant’s county of residence"
    ]
  },
  "official_source": "https://tax.illinois.gov/localgovernments/property/taxrelief.html",
  "gotchas": [
    "This freezes assessed value, not the tax bill; taxes can still rise if rates go up.",
    "It is not an automatic benefit; families usually must apply each year.",
    "Income is measured as total household income, not just the senior’s personal income.",
    "County procedures differ, so the local assessor’s instructions control filing details and deadlines.",
    "Some county materials emphasize that the property must already have been owned and occupied for a qualifying period before the freeze can be granted."
  ],
  "data_shape_notes": "This is a county-administered statewide property tax exemption with a single income threshold, an age gate, and a benefit based on freezing assessed value rather than issuing a cash payment or service."
}

{
  "name": "Illinois Benefit Access Program",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "basis": "Total gross income for the last closed tax year",
      "household_table": [
        {
          "household_size": 1,
          "limit": 33562
        },
        {
          "household_size": 2,
          "limit": 44533
        },
        {
          "household_size": 3,
          "limit": 55500
        }
      ],
      "rules": [
        "If married and living together on December 31 of the prior year, spouse income must be included.",
        "If the spouse died during the prior year, the applicant files as single and counts only their own income.",
        "Do not include the income of a Qualified Additional Resident."
      ]
    },
    "asset_limits": "No asset limit was identified in the official program information reviewed. Eligibility is described in terms of income, age/disability, and Illinois residency rather than assets.",
    "other_requirements": [
      "Must be an Illinois resident.",
      "Must be at least 65 years old, or be 16 years of age or older before January 1 of the current year and have a disability.",
      "Eligibility is determined through the online application.",
      "For the Ride Free Transit Benefit, the income limits are the same as above."
    ]
  },
  "benefits": {
    "type": "in_kind",
    "value": "Provides two main benefits: a license plate fee discount and a Ride Free Transit Benefit. The license plate discount reduces annual registration fees for eligible seniors and persons with disabilities. The Ride Free Transit Benefit provides free rides on participating public transit systems in Illinois.",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online application: https://ilaging.illinois.gov/benefitsaccess/benefit-access-online-application.html",
      "Phone help line: 1-800-252-8966",
      "TTY: 1-888-206-1327",
      "Assistance through a local Area Agency on Aging",
      "Assistance through a Senior Health Assistance Program office"
    ],
    "processing_time": "Approximately 12 weeks to determine eligibility; after approval, wait 10 business days before the license plate discount is available.",
    "waitlist": null,
    "forms": [
      "Benefit Access Application"
    ],
    "documents": [
      "Proof of age or disability if requested",
      "Income information for the last closed tax year",
      "Spouse income information if married and living together on December 31 of the prior year",
      "Illinois residency information",
      "Any information needed to verify household size and qualified additional residents"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available to eligible Illinois residents statewide; benefits are tied to Illinois transit systems and Illinois Secretary of State vehicle services.",
    "regional_variations": "The program’s eligibility rules are statewide, but transit benefit use depends on participating local transit systems. Processing support may be obtained through local Area Agencies on Aging or Senior Health Assistance Program offices, so access to help can vary by region.",
    "offices_or_providers": [
      "Illinois Department on Aging",
      "Illinois Secretary of State facilities for license plate discounts",
      "Local Area Agencies on Aging",
      "Senior Health Assistance Program offices"
    ]
  },
  "official_source": "https://ilaging.illinois.gov/benefitsaccess.html",
  "gotchas": [
    "The program is not a cash benefit; it mainly provides a license plate discount and free transit rides.",
    "Applicants must use the online application; paper applications are not available.",
    "Income is based on the last closed tax year, not current monthly income.",
    "Married applicants often miss the rule that spouse income counts if living together on December 31 of the prior year.",
    "A Qualified Additional Resident can affect household size, but that person’s income is not counted.",
    "Approval does not immediately activate the license plate discount; it can take 10 business days after approval."
  ],
  "data_shape_notes": "This program is income-based, household-size based, and benefit-specific: one application determines eligibility for two linked benefits, with separate activation steps for the license plate discount and transit benefit."
}
